#!/usr/bin/env python3
"""
apply_fixes.py - applies the v2 fixes to the hackathon repo.

Run from the repository root (the folder that contains src/ and data/):
    python apply_fixes.py

What it does:
  1. Backs up every file it will overwrite to .pre_fix_backup/<timestamp>/
  2. Writes the fixed files (55 files)
  3. Moves stale artefacts (old leaky metrics, empty Docker files) into the backup
  4. Clears __pycache__ folders
Nothing is deleted permanently; restore by copying files back from the backup.
"""
